-- Duplicate-submission protection
ALTER TABLE public.responses ADD COLUMN IF NOT EXISTS submission_id UUID;
CREATE UNIQUE INDEX IF NOT EXISTS responses_submission_subject_uniq
  ON public.responses (submission_id, subject) WHERE submission_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS responses_submitted_at_idx ON public.responses (submitted_at DESC);